import { MouseCoordinate } from '../../../../core/types/overlays.js';
import { isVertical } from '../../../functions/layout.js';
import { DimensionXYPoint } from '../../../types/categorical-bar-chart-data.js';
import { Layout } from '../../../types/categorical-bar-chart.js';

const horizontalDistance = (
  mousePosition: MouseCoordinate,
  point: DimensionXYPoint,
) => Math.sqrt(Math.pow(mousePosition.x - point.x, 2));

const verticalDistance = (
  mousePosition: MouseCoordinate,
  point: DimensionXYPoint,
) => Math.sqrt(Math.pow(mousePosition.y - point.y, 2));

export const findClosestDimensionPoint = (
  layout: Layout,
  mouseCoords: MouseCoordinate,
  closestDimensionPoints: DimensionXYPoint[],
): DimensionXYPoint | undefined => {
  if (mouseCoords && closestDimensionPoints.length > 0) {
    const closestPoint = closestDimensionPoints.reduce((p1, p2) => {
      if (isVertical(layout)) {
        return horizontalDistance(mouseCoords, p1) <
          horizontalDistance(mouseCoords, p2)
          ? p1
          : p2;
      }

      return verticalDistance(mouseCoords, p1) <
        verticalDistance(mouseCoords, p2)
        ? p1
        : p2;
    });

    return closestPoint;
  }

  return undefined;
};
